let subject='Matematik',qi=0,color='#34483d',tool='pen',strokes=[],undoStack=[],redoStack=[],drawing=null,saveTimeout,toastTimeout;
let settings={questionWriting:true,theme:'light',paper:'dots',fingerDrawing:false,language:'tr',questionMode:'open',accent:'lavender',pageColor:'auto',eraserMode:'stroke',customAccent:'#8578a0',clearOnNewQuestion:true,educationMode:'university',choiceCount:4};try{const stored=JSON.parse(localStorage.getItem('forma-settings')||'{}');if(['light','dark','system'].includes(stored.theme))settings.theme=stored.theme;if(['dots','grid','lines','plain'].includes(stored.paper))settings.paper=stored.paper;if(['tr','en'].includes(stored.language))settings.language=stored.language;if(['multiple','open'].includes(stored.questionMode))settings.questionMode=stored.questionMode;if(['none','lavender','green','blue','amber','rose','custom'].includes(stored.accent))settings.accent=stored.accent;if(stored.pageColor==='auto'||validInk(stored.pageColor))settings.pageColor=stored.pageColor;if(['stroke','point'].includes(stored.eraserMode))settings.eraserMode=stored.eraserMode;if(validInk(stored.customAccent))settings.customAccent=stored.customAccent;if(['high-school','university'].includes(stored.educationMode))settings.educationMode=stored.educationMode;if([4,5,6,7].includes(stored.choiceCount))settings.choiceCount=stored.choiceCount;settings.clearOnNewQuestion=stored.clearOnNewQuestion!==false;settings.fingerDrawing=stored.fingerDrawing===true;if(stored.defaultsVersion!==2){settings.eraserMode='stroke';settings.educationMode='university';}if(typeof stored.questionWriting==='boolean')settings.questionWriting=stored.questionWriting;settings.defaultsVersion=2;localStorage.setItem('forma-settings',JSON.stringify(settings));}catch{}
let documentHeight=3600,panGesture=null,formulaSubject='Matematik',formulaTopic=0,formulaFollowsQuestion=true,formulaProgram='general-math-1';
let database={};try{database=JSON.parse(localStorage.getItem('forma-v1')||'{}')}catch{}
let questionStreams={};try{questionStreams=JSON.parse(localStorage.getItem('forma-question-streams')||'{}');}catch{}
let activeQuestion=null,activeKey=null,legacyQuestion=false;
let universitySelection={program:'general-math-1',topic:'general',subtopic:'mixed'};
function normalizeUniversitySelection(value){const program=UniversityQuestions.programs.some(program=>program.id===value?.program)?value.program:'general-math-1',bank=UniversityQuestions.bankFor(program),topic=bank.topics.some(topic=>topic.id===value?.topic&&topic.ready)?value.topic:'general',subtopic=bank.subtopicsFor(topic).some(sub=>sub.id===value?.subtopic)?value.subtopic:'mixed';return{program,topic,subtopic};}
try{universitySelection=normalizeUniversitySelection(JSON.parse(localStorage.getItem('forma-university-selection')||'{}'));}catch{}
let programSelections={};try{programSelections=JSON.parse(localStorage.getItem('forma-university-program-selections')||'{}');}catch{}
function storeUniversitySelection(){programSelections[universitySelection.program]=structuredClone(universitySelection);try{localStorage.setItem('forma-university-selection',JSON.stringify(universitySelection));localStorage.setItem('forma-university-program-selections',JSON.stringify(programSelections));}catch{}}
function switchUniversityProgram(program){if(program===universitySelection.program)return;storeUniversitySelection();universitySelection=normalizeUniversitySelection(programSelections[program]||{program});storeUniversitySelection();setSubject(subject);}
function streamScope(value=subject){return settings.educationMode==='university'?value+':university:'+(universitySelection.program==='differential-equations'?'ode:':universitySelection.program==='discrete-math'?'discrete:':universitySelection.program==='linear-algebra'?'linear:':universitySelection.program==='geometry'?'geometry:':universitySelection.program==='solid-geometry'?'solid:':universitySelection.program==='analytic-geometry'?'analytic:':universitySelection.program==='general-math-2'?'math2:':'')+universitySelection.topic+':'+(universitySelection.topic==='general'?'mixed':universitySelection.subtopic):value;}
function universityReady(){return settings.educationMode!=='university'||subject==='Matematik';}
function selectedTopicLabel(){return settings.educationMode==='university'?t(UniversityQuestions.topicLabel(subject==='Matematik'?universitySelection.topic:'general')):course().topic;}
function questionTopicLabel(question=activeQuestion){return question?.educationMode==='university'?t(UniversityQuestions.topicLabel(question.topicId||'trig'))+' · '+t(UniversityQuestions.subtopicLabel(question.subtopicId)):courses[subject].topic;}
function resizeUnsavedChoices(persistChanges=true){if(!activeQuestion?.generatorVersion||activeQuestion.supportsChoices===false||database[key()]?.saved)return;const entry=database[key()],selected=Number.isInteger(entry?.answer)?activeQuestion.choices[entry.answer]:null;activeQuestion=QuestionEngine.withChoiceCount(activeQuestion,settings.choiceCount);if(entry){entry.question=structuredClone(activeQuestion);if(selected!==null){const index=activeQuestion.choices.indexOf(selected);if(index>=0)entry.answer=index;else delete entry.answer;}if(persistChanges)save();}}
function streamFor(value){return StudySessions.resolve(value,{subject,educationMode:settings.educationMode,selection:structuredClone(universitySelection)}).stream;}
function storeStreams(){StudySessions.persist();try{localStorage.setItem('forma-question-streams',JSON.stringify(questionStreams));}catch{}}
function selectGeneratedQuestion(index){if(!universityReady()){activeQuestion=null;activeKey=null;return;}const scope=streamScope(),stream=streamFor(scope);qi=index;const generated=settings.educationMode==='university'?UniversityQuestions.generate(subject,stream.seed,index,universitySelection,settings.choiceCount):QuestionEngine.withChoiceCount(QuestionEngine.generate(subject,stream.seed,index),settings.choiceCount);activeQuestion={...generated,educationMode:settings.educationMode};activeKey=StudySessions.current().id+':'+subject+(settings.educationMode==='university'?':u:'+scope:':g')+':'+activeQuestion.id;
// Keep saved snapshots, including older general-exam questions, stable after catalog updates.
if(!StudySessions.current()&&!database[activeKey]){const remembered=Object.entries(database).find(([k,entry])=>entry.question?.generatorVersion&&entry.subject===subject&&entry.streamScope===scope&&entry.questionIndex===index&&Number(entry.question.id.split('-')[1])===(stream.seed>>>0));if(remembered){activeKey=remembered[0];activeQuestion=structuredClone(remembered[1].question);}}
legacyQuestion=false;stream.cursor=index;storeStreams();}
const key=()=>activeKey||`${subject}:${qi}`;
function currentQuestion(){if(!activeQuestion)selectGeneratedQuestion(streamFor(streamScope()).cursor);return activeQuestion.generatorVersion?QuestionEngine.localize(activeQuestion,settings.language):I18n.course(activeQuestion);}
function settleDrawing(){if(drawing)finishDrawing({pointerId:drawing.pointerId});panGesture=null;}
function boardSnapshot(){return{strokes:structuredClone(strokes),documentHeight,scrollTop:$('paper-scroll').scrollTop,coordinatesVersion:2};}
const course=()=>I18n.course(courses[subject]);
function toast(message){$('toast').textContent=t(message);$('toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.remove('show'),3200)}
function persist(){try{localStorage.setItem('forma-v1',JSON.stringify(database));updateCount();return true;}catch{toast('Not kaydedilemedi.');return false;}}
function isSavedStudy(entry){if(entry.sessionId&&entry.type!=='session')return false;return entry.saved||(!entry.question?.generatorVersion&&entry.strokes?.length);}
function updateCount(){$('note-count').textContent=Object.values(database).filter(isSavedStudy).length}updateCount();
function syncSavedSession(session){const id='session:'+session.id,previous=database[id];if(!previous)return;const current=database[key()];database[id]={...previous,question:structuredClone(current?.question||activeQuestion),questionIndex:qi,currentKey:key(),updated:session.updated,session:structuredClone(session)};}
function save(){if(!activeQuestion)return false;const entry=database[key()]||{},session=StudySessions.current(),belongs=session&&key().startsWith(session.id+':');if(!belongs&&!entry.saved&&!strokes.length&&!Number.isInteger(entry.answer)){if(database[key()]){delete database[key()];persist();}return true;}database[key()]={...entry,subject,questionIndex:qi,topic:questionTopicLabel(),educationMode:activeQuestion.educationMode||'high-school',streamScope:belongs?session.scope:streamScope(),question:structuredClone(activeQuestion),strokes:structuredClone(strokes),coordinatesVersion:2,documentHeight,scrollTop:$('paper-scroll').scrollTop,updated:new Date().toISOString(),...(belongs?{sessionId:session.id}: {})};if(belongs){if(!session.questionKeys.includes(key()))session.questionKeys.push(key());session.currentKey=key();session.updated=new Date().toISOString();session.stream.cursor=qi;if(window.ModuleWorkspace?.capture&&window.ModuleWorkspace.inspect().study===session.id)session.modules=ModuleWorkspace.capture();syncSavedSession(session);if(!StudySessions.persist()){toast('Not kaydedilemedi.');return false;}}return persist();}
function saveSession(){settleDrawing();clearTimeout(saveTimeout);if(!save())return false;const session=StudySessions.current();if(!session){database[key()]={...database[key()],saved:true};return save();}for(const id of session.questionKeys)if(database[id])database[id].saved=true;const current=database[key()],id='session:'+session.id;database[id]={...database[id],...current,type:'session',saved:true,sessionId:session.id,currentKey:key(),session:structuredClone(session)};return persist();}
function beginNewSession(){settleDrawing();clearTimeout(saveTimeout);save();window.ModuleWorkspace?.suspend();closeAllFloatingWindows();StudySessions.create(streamScope(),{subject,educationMode:settings.educationMode,selection:structuredClone(universitySelection)});selectGeneratedQuestion(0);loadQuestion();toast('Yeni oturum başladı.');}
function openSavedSession(entry,questionKey=null){const session=StudySessions.get(entry.sessionId)||structuredClone(entry.session);if(!session)return;settings.educationMode=session.educationMode;universitySelection=normalizeUniversitySelection(session.selection);subject=session.subject;storeUniversitySelection();storeSettings();StudySessions.restore(session);applySettings();renderSubject();const selected=questionKey||entry.currentKey||session.questionKeys.at(-1),question=database[selected];if(!question?.question)return;qi=question.questionIndex;activeKey=selected;activeQuestion=structuredClone(question.question);legacyQuestion=false;session.stream.cursor=qi;StudySessions.persist();enter();}

function scheduleSave(){clearTimeout(saveTimeout);saveTimeout=setTimeout(save,450)}
function setSubject(value){subject=value;if(universityReady())selectGeneratedQuestion(streamFor(streamScope(value)).cursor);else{activeQuestion=null;activeKey=null;StudySessions.pause();}formulaSubject=value;formulaTopic=0;formulaProgram=universitySelection.program;formulaFollowsQuestion=true;renderSubject();}
function renderSubject(){document.querySelectorAll('.subject').forEach(element=>element.classList.toggle('selected',element.dataset.subject===subject));if(settings.educationMode==='university'&&subject!=='Matematik'){ScienceCatalog.render(subject);return;}const university=settings.educationMode==='university';$('education-badge').textContent=university?t('Üniversite modu')+' · '+t(UniversityQuestions.programLabel(universitySelection.program)):t('Lise modu');$('university-program').hidden=!university||subject!=='Matematik';$('university-program-options').innerHTML=UniversityQuestions.programs.map(program=>`<button data-university-program="${program.id}" aria-pressed="${program.id===universitySelection.program}">${t(program.label)}</button>`).join('');$('university-subtopics').hidden=!university||subject!=='Matematik'||universitySelection.topic==='general';$('university-status').hidden=!university;$('university-status').textContent=universityReady()?t(universitySelection.topic==='general'?(universitySelection.program==='differential-equations'?'Tüm Diferansiyel Denklemler konularından karışık.':universitySelection.program==='discrete-math'?'Tüm Ayrık Matematik konularından karışık.':universitySelection.program==='linear-algebra'?'Tüm Lineer Cebir konularından karışık.':universitySelection.program==='geometry'?'Tüm Geometri konularından karışık.':universitySelection.program==='solid-geometry'?'Tüm Katı Cisimler konularından karışık.':universitySelection.program==='analytic-geometry'?'Tüm Analitik Geometri konularından karışık.':universitySelection.program==='general-math-2'?'Tüm Genel Matematik 2 konularından karışık.':'Tüm Genel Matematik 1 konularından karışık.'):''):t('Üniversite soruları hazırlanıyor.');if(university){$('topics').innerHTML=UniversityQuestions.topicsFor(subject,universitySelection.program).map(topic=>`<button class="topic ${topic.id===universitySelection.topic?'active':''}" data-university-topic="${topic.id}" ${!topic.ready?'disabled':''}>${t(topic.label)}${!topic.ready?`<span class="soon">${t('yakında')}</span>`:icon('arrow')}</button>`).join('');$('university-subtopic-options').innerHTML=UniversityQuestions.subtopicsFor(universitySelection.topic,universitySelection.program).map(topic=>`<button data-university-subtopic="${topic.id}" aria-pressed="${topic.id===universitySelection.subtopic}">${t(topic.label)}</button>`).join('');}else $('topics').innerHTML=course().topics.map((topic,i)=>`<button class="topic ${i===0?'active':''}" data-topic="${i}" ${i?`aria-label="${topic} — ${t('yakında')}"`:''}>${topic}${i?`<span class="soon">${t('yakında')}</span>`:icon('arrow')}</button>`).join('');$('session-subject').textContent=t(subject).toLocaleUpperCase(I18n.locale());$('session-topic').textContent=selectedTopicLabel();$('session-subtopic').hidden=!university;$('session-subtopic').textContent=universityReady()?t(universitySelection.topic==='general'?'Genel karma':UniversityQuestions.subtopicLabel(universitySelection.subtopic)):t('yakında');$('start').disabled=!universityReady();}
$('university-program-options').onclick=event=>{const science=event.target.closest('[data-science-program]');if(science){ScienceCatalog.select(subject,'program',science.dataset.scienceProgram);renderSubject();return;}const button=event.target.closest('[data-university-program]');if(button)switchUniversityProgram(button.dataset.universityProgram);};
document.querySelectorAll('.subject').forEach(element=>element.onclick=()=>setSubject(element.dataset.subject));
$('topics').onclick=event=>{const science=event.target.closest('[data-science-topic]');if(science){ScienceCatalog.select(subject,'topic',science.dataset.scienceTopic);renderSubject();return;}const button=event.target.closest('button');if(!button)return;if(button.dataset.universityTopic){universitySelection.topic=button.dataset.universityTopic;universitySelection.subtopic='mixed';storeUniversitySelection();setSubject(subject);}else if(button.dataset.topic!=='0')toast('Bu konu hazırlanıyor.');};
$('university-subtopic-options').onclick=event=>{const science=event.target.closest('[data-science-subtopic]');if(science){ScienceCatalog.select(subject,'subtopic',science.dataset.scienceSubtopic);renderSubject();return;}const button=event.target.closest('[data-university-subtopic]');if(!button)return;universitySelection.subtopic=button.dataset.universitySubtopic;storeUniversitySelection();setSubject(subject);};setSubject(subject);
let widgetExplorerOpen=false,widgetExplorerAnimation=null;
function toggleWidgetExplorer(open,restoreFocus=true){const panel=$('widget-explorer'),shade=$('widget-explorer-shade');widgetExplorerOpen=open;panel.dataset.open=String(open);$('widgets-open').setAttribute('aria-expanded',String(open));if(widgetExplorerAnimation)widgetExplorerAnimation.cancel();const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(open){panel.hidden=false;shade.hidden=false;widgetExplorerAnimation=panel.animate([{transform:'translateX(100%)',opacity:.5},{transform:'translateX(0)',opacity:1}],{duration:reduced?0:220,easing:'cubic-bezier(.2,.7,.2,1)'});$('widgets-close').focus();}else{shade.hidden=true;if(panel.hidden)return;widgetExplorerAnimation=panel.animate([{transform:'translateX(0)',opacity:1},{transform:'translateX(100%)',opacity:.5}],{duration:reduced?0:180,easing:'ease-in'});widgetExplorerAnimation.onfinish=()=>{if(!widgetExplorerOpen)panel.hidden=true;};if(restoreFocus&&panel.contains(document.activeElement))$('widgets-open').focus();}}
$('widgets-open').onclick=()=>toggleWidgetExplorer(!widgetExplorerOpen);
$('widgets-close').onclick=()=>toggleWidgetExplorer(false);
$('widget-explorer-shade').onclick=()=>toggleWidgetExplorer(false);
$('widget-explorer').addEventListener('click',event=>{if(event.target.closest('.widget-launch'))toggleWidgetExplorer(false,false);});
$('widget-explorer').addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();toggleWidgetExplorer(false);}else if(event.key==='Tab'){const buttons=[...$('widget-explorer').querySelectorAll('button:not(:disabled)')],first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});

let returnToStudy=false;
function setScreen(value){if(widgetExplorerOpen)toggleWidgetExplorer(false,false);requestAnimationFrame(()=>{const page=$(value==='notes'?'notes-page':value);if(page&&!page.hidden&&!matchMedia('(prefers-reduced-motion: reduce)').matches){page.getAnimations().forEach(a=>a.cancel());page.animate([{opacity:0,transform:'translateY(9px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.2,.7,.2,1)'});}});document.body.dataset.screen=value;$('home-nav').classList.toggle('active',value!=='notes');$('notes-nav').classList.toggle('active',value==='notes');}
function enter(){if(!universityReady())return;setScreen('workspace');$('notes-page').hidden=true; $('home').hidden=true;$('workspace').hidden=false;loadQuestion();window.scrollTo(0,0);requestAnimationFrame(resizeCanvas)}
function home(){closePenPalette(false);closeEraserPalette(false);setScreen('home');$('notes-page').hidden=true;if(!$('workspace').hidden)save();window.ModuleWorkspace?.suspend();closeAllFloatingWindows();$('workspace').hidden=true;$('home').hidden=false;window.scrollTo(0,0)}
