// The stopwatch is independent of questions, autosave and the drawing surface.
let stopwatch={elapsedMs:0,running:false,startedAt:0};
try{const stored=JSON.parse(localStorage.getItem('forma-stopwatch')||'{}');if(Number.isFinite(stored.elapsedMs)&&stored.elapsedMs>=0)stopwatch.elapsedMs=stored.elapsedMs;if(stored.running===true&&Number.isFinite(stored.startedAt)&&stored.startedAt>0){stopwatch.running=true;stopwatch.startedAt=stored.startedAt;}}catch{}
function stopwatchElapsed(){return stopwatch.elapsedMs+(stopwatch.running?Math.max(0,Date.now()-stopwatch.startedAt):0);}
