$('stopwatch-start').onclick=()=>{if(typeof toggleCountdown==='function'&&timerState.mode==='countdown'){toggleCountdown();return;}if(stopwatch.running){stopwatch.elapsedMs=stopwatchElapsed();stopwatch.running=false;stopwatch.startedAt=0;}else{stopwatch.startedAt=Date.now();stopwatch.running=true;}saveStopwatch();renderStopwatch();};
$('stopwatch-reset').onclick=()=>{if(typeof resetCountdown==='function'&&timerState.mode==='countdown'){resetCountdown();return;}stopwatch={elapsedMs:0,running:false,startedAt:0};saveStopwatch();renderStopwatch();};
