function eraseWholeStrokes(a,b){const removed=new Set(),hit=new Set();for(const stroke of strokes){if(stroke.tool==='eraser'||!stroke.points.length)continue;let bounds=strokeBounds.get(stroke);if(!bounds||bounds.minX===undefined){bounds={minX:Infinity,maxX:-Infinity,minY:Infinity,maxY:-Infinity};for(const p of stroke.points){bounds.minX=Math.min(bounds.minX,p.x);bounds.maxX=Math.max(bounds.maxX,p.x);bounds.minY=Math.min(bounds.minY,p.y);bounds.maxY=Math.max(bounds.maxY,p.y);}strokeBounds.set(stroke,bounds);}const radius=drawing.width/2+stroke.width*1.1; if(bounds.maxX+radius<Math.min(a.x,b.x)||bounds.minX-radius>Math.max(a.x,b.x)||bounds.maxY+radius<Math.min(a.y,b.y)||bounds.minY-radius>Math.max(a.y,b.y))continue;const points=stroke.points;let touched=points.length===1?segmentDistance(points[0],a,b)<=drawing.width/2+contactStrokeWidth(stroke,points[0])/2:false;for(let i=1;!touched&&i<points.length;i++)touched=segmentsNear(a,b,points[i-1],points[i],drawing.width/2+contactStrokeWidth(stroke,points[i],points[i-1])/2);if(touched){hit.add(stroke);if(stroke.gestureId)removed.add(stroke.gestureId);}}if(hit.size){strokes=strokes.filter(stroke=>!hit.has(stroke)&&!(stroke.tool!=='eraser'&&stroke.gestureId&&removed.has(stroke.gestureId)));inkDirty=true;}}

